dashboard.definition:
{
  "title": "AD Health & Performance",
  "description": "Domain controller health and performance: AD health-check, Netlogon and DNS-health events flagging problems, data freshness per DC, and Perfmon counters for NTDS (LDAP, replication queue, threads), CPU, DNS and DFS replicated folders. Problem events are detected by keywords (macro adx_problem_terms) because the free-text health sources have no fixed schema.",
  "inputs": {
    "input_global_trp": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    },
    "input_pm_st": {
      "type": "input.dropdown",
      "title": "Perfmon sourcetype",
      "options": {
        "token": "pm_st",
        "defaultValue": "Perfmon:NTDS",
        "items": [
          {
            "label": "NTDS",
            "value": "Perfmon:NTDS"
          },
          {
            "label": "DNS",
            "value": "Perfmon:DNS"
          },
          {
            "label": "DFS Replicated Folders",
            "value": "Perfmon:DFS_Replicated_Folders"
          },
          {
            "label": "Network Interface",
            "value": "Perfmon:Network_Interface"
          },
          {
            "label": "Processor",
            "value": "Perfmon:Processor"
          }
        ]
      }
    },
    "input_pm_counter": {
      "type": "input.dropdown",
      "title": "Counter",
      "options": {
        "token": "pm_counter",
        "selectFirstSearchResult": true
      },
      "dataSources": {
        "primary": "ds_counters"
      }
    }
  },
  "defaults": {},
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "title": "DCs reporting health",
      "dataSources": {
        "primary": "ds_1"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "title": "DCs with a problem",
      "dataSources": {
        "primary": "ds_2"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "title": "SYSVOL not shared",
      "dataSources": {
        "primary": "ds_3"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "title": "DNS servers with a problem",
      "dataSources": {
        "primary": "ds_4"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "title": "Global catalogs",
      "dataSources": {
        "primary": "ds_5"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off"
      }
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "title": "Clients without AD site (24h)",
      "dataSources": {
        "primary": "ds_6"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#FFC300",
            "from": 1,
            "to": 50
          },
          {
            "value": "#B0413E",
            "from": 50
          }
        ]
      }
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "title": "Silent sources (no data > 60 min)",
      "dataSources": {
        "primary": "ds_7"
      },
      "options": {
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "majorColor": "> majorValue | rangeValue(majorColorEditorConfig)"
      },
      "context": {
        "majorColorEditorConfig": [
          {
            "value": "#65A637",
            "to": 1
          },
          {
            "value": "#B0413E",
            "from": 1
          }
        ]
      }
    },
    "viz_8": {
      "type": "splunk.table",
      "title": "Domain controllers - health, roles and inventory",
      "dataSources": {
        "primary": "ds_8"
      },
      "options": {
        "count": 12,
        "wrap": true,
        "columnFormat": {
          "status": {
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusColorConfig)"
          }
        }
      },
      "description": "Latest MSAD:NT6:Health state of each DC. PROBLEM = SYSVOL not shared, processes not OK, DNS registration failed, or a monitored service down (ntfrs is ignored: expected stopped with DFSR). fsmo = FSMO roles held; istg = intersite topology generator.",
      "context": {
        "statusColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "PROBLEM",
            "value": "#B0413E"
          }
        ]
      }
    },
    "viz_9": {
      "type": "splunk.pie",
      "title": "Domain controllers by operating system",
      "dataSources": {
        "primary": "ds_9"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_10": {
      "type": "splunk.bar",
      "title": "Domain controllers by AD site",
      "dataSources": {
        "primary": "ds_10"
      },
      "options": {
        "legendDisplay": "off"
      }
    },
    "viz_11": {
      "type": "splunk.table",
      "title": "FSMO role holders",
      "dataSources": {
        "primary": "ds_11"
      },
      "options": {
        "count": 6,
        "wrap": true
      }
    },
    "viz_12": {
      "type": "splunk.table",
      "title": "DNS servers - health",
      "dataSources": {
        "primary": "ds_12"
      },
      "options": {
        "count": 8,
        "wrap": true,
        "columnFormat": {
          "status": {
            "rowBackgroundColors": "> table | seriesByName(\"status\") | matchValue(statusColorConfig)"
          }
        }
      },
      "description": "Latest MSAD:NT6:DNS-Health state of each DNS server (service status, DNSSEC, recursion, scavenging interval, forwarders).",
      "context": {
        "statusColorConfig": [
          {
            "match": "OK",
            "value": "#65A637"
          },
          {
            "match": "PROBLEM",
            "value": "#B0413E"
          }
        ]
      }
    },
    "viz_13": {
      "type": "splunk.line",
      "title": "Highest USN by DC (directory change activity)",
      "dataSources": {
        "primary": "ds_13"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_14": {
      "type": "splunk.column",
      "title": "Netlogon site affinity over time",
      "dataSources": {
        "primary": "ds_14"
      },
      "options": {
        "legendDisplay": "bottom",
        "stackMode": "stacked"
      }
    },
    "viz_15": {
      "type": "splunk.table",
      "title": "Subnets missing from AD Sites and Services (NO_CLIENT_SITE)",
      "dataSources": {
        "primary": "ds_15"
      },
      "options": {
        "count": 10,
        "wrap": true
      },
      "description": "Clients authenticating from an IP that is not in any AD subnet (Netlogon NO_CLIENT_SITE): they may be served by a remote DC. Add these subnets to the right site in AD Sites and Services. The /24 grouping is an approximation."
    },
    "viz_16": {
      "type": "splunk.table",
      "title": "Clients without AD site - top hosts",
      "dataSources": {
        "primary": "ds_16"
      },
      "options": {
        "count": 10,
        "wrap": true
      }
    },
    "viz_17": {
      "type": "splunk.table",
      "title": "Data freshness per DC and source (minutes since last event)",
      "dataSources": {
        "primary": "ds_17"
      },
      "options": {
        "count": 15,
        "wrap": true
      },
      "description": "Empty cell = that DC never sent that source in the last 24h."
    },
    "viz_18": {
      "type": "splunk.line",
      "title": "NTDS - LDAP searches/sec",
      "dataSources": {
        "primary": "ds_18"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_19": {
      "type": "splunk.line",
      "title": "NTDS - pending replication operations",
      "dataSources": {
        "primary": "ds_19"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_20": {
      "type": "splunk.line",
      "title": "NTDS - DS threads in use",
      "dataSources": {
        "primary": "ds_20"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_21": {
      "type": "splunk.line",
      "title": "CPU - % Processor Time (_Total)",
      "dataSources": {
        "primary": "ds_21"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_22": {
      "type": "splunk.line",
      "title": "DNS - queries received/sec",
      "dataSources": {
        "primary": "ds_22"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_23": {
      "type": "splunk.line",
      "title": "DNS - recursive query failures/sec",
      "dataSources": {
        "primary": "ds_23"
      },
      "options": {
        "legendDisplay": "bottom"
      }
    },
    "viz_24": {
      "type": "splunk.line",
      "title": "Perfmon explorer: pick any counter",
      "dataSources": {
        "primary": "ds_24"
      },
      "options": {
        "legendDisplay": "bottom"
      },
      "description": "Choose a Perfmon sourcetype then a counter (NTDS, DNS, DFS Replicated Folders, Network Interface, Processor)."
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "DCs reporting health",
      "options": {
        "query": "`adx_dc_health` | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "DCs with a problem",
      "options": {
        "query": "`adx_dc_health` | where status=\"PROBLEM\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "SYSVOL not shared",
      "options": {
        "query": "`adx_dc_health` | where sysvol!=\"True\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "DNS servers with a problem",
      "options": {
        "query": "`adx_dns_health` | where status=\"PROBLEM\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Global catalogs",
      "options": {
        "query": "`adx_dc_health` | where gc=\"True\" | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Clients without AD site (24h)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | stats dc(src_ip)",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Silent sources (no data > 60 min)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | where last<now()-3600 | stats count",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Domain controllers - health, roles and inventory",
      "options": {
        "query": "`adx_dc_health` | eval last_report=minutes_ago.\" min ago\", problem=coalesce(mvjoin(problem,\"; \"),\"-\") | sort - status, site, Server | table site Server status problem os gc rodc fsmo istg sysvol procs_ok dns_register svc_down usn forest_level domain_level schema last_report",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Domain controllers by operating system",
      "options": {
        "query": "`adx_dc_health` | stats count by os",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Domain controllers by AD site",
      "options": {
        "query": "`adx_dc_health` | stats count by site",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "FSMO role holders",
      "options": {
        "query": "`adx_dc_health` | where len(fsmo)>0 | table Server fsmo site",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "DNS servers - health",
      "options": {
        "query": "`adx_dns_health` | eval problem=coalesce(mvjoin(problem,\"; \"),\"-\"), forwarders=mvjoin(forwarders,\", \"), last_report=minutes_ago.\" min ago\" | sort - status, Server | table Server status problem dns_status started dnssec no_recursion scavenging_h forwarders os last_report",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_13": {
      "type": "ds.search",
      "name": "Highest USN by DC (directory change activity)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Health\" | timechart span=1h max(HighestUSN) by Server limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_14": {
      "type": "ds.search",
      "name": "Netlogon site affinity over time",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" | fillnull value=\"OTHER\" msad_affinity | timechart span=1h count by msad_affinity",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_15": {
      "type": "ds.search",
      "name": "Subnets missing from AD Sites and Services (NO_CLIENT_SITE)",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | eval subnet=replace(src_ip,\"^(\\d+\\.\\d+\\.\\d+)\\.\\d+\",\"\\1.0/24\") | stats count as requests, dc(src_ip) as clients, dc(src_host) as hosts, values(host) as seen_by_dc, latest(src_host) as sample_host by subnet | sort - requests",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_16": {
      "type": "ds.search",
      "name": "Clients without AD site - top hosts",
      "options": {
        "query": "`adx_msad_index` sourcetype=\"MSAD:NT6:Netlogon\" msad_affinity=NO_CLIENT_SITE | stats count as requests, latest(src_ip) as src_ip, latest(src_domain) as domain, values(host) as seen_by_dc by src_host | sort - requests",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_17": {
      "type": "ds.search",
      "name": "Data freshness per DC and source (minutes since last event)",
      "options": {
        "query": "| multisearch [search `adx_msad_index` (sourcetype=\"MSAD:NT6:Health\" OR sourcetype=\"MSAD:NT6:Replication\" OR sourcetype=\"MSAD:NT6:Netlogon\" OR sourcetype=\"MSAD:NT6:DNS-Health\") | fields host sourcetype _time] [search `adx_perfmon_index` (sourcetype=\"Perfmon:NTDS\" OR sourcetype=\"Perfmon:Processor\" OR sourcetype=\"Perfmon:DNS\" OR sourcetype=\"Perfmon:DFS_Replicated_Folders\") | fields host sourcetype _time] | stats max(_time) as last by host sourcetype | eval minutes_ago=round((now()-last)/60,0) | chart latest(minutes_ago) as m over host by sourcetype",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_18": {
      "type": "ds.search",
      "name": "NTDS - LDAP searches/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"LDAP Searches/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_19": {
      "type": "ds.search",
      "name": "NTDS - pending replication operations",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DRA Pending Replication Operations\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_20": {
      "type": "ds.search",
      "name": "NTDS - DS threads in use",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:NTDS\" counter=\"DS Threads in Use\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_21": {
      "type": "ds.search",
      "name": "CPU - % Processor Time (_Total)",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:Processor\" counter=\"% Processor Time\" instance=\"_Total\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_22": {
      "type": "ds.search",
      "name": "DNS - queries received/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Total Query Received/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_23": {
      "type": "ds.search",
      "name": "DNS - recursive query failures/sec",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"Perfmon:DNS\" counter=\"Recursive Query Failure/sec\" | timechart span=5m avg(Value) by host limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_24": {
      "type": "ds.search",
      "name": "Perfmon explorer: pick any counter",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" counter=\"$pm_counter$\" | eval series=host.\" \".coalesce(instance,\"\") | timechart span=5m avg(Value) by series limit=15",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_counters": {
      "type": "ds.search",
      "name": "Perfmon counters",
      "options": {
        "query": "`adx_perfmon_index` sourcetype=\"$pm_st$\" | stats count by counter | eval label=counter, value=counter | sort label | fields label value",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 3676,
      "display": "auto-scale"
    },
    "structure": [
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 206,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_3",
        "type": "block",
        "position": {
          "x": 412,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_4",
        "type": "block",
        "position": {
          "x": 618,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_5",
        "type": "block",
        "position": {
          "x": 824,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_6",
        "type": "block",
        "position": {
          "x": 1030,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_7",
        "type": "block",
        "position": {
          "x": 1236,
          "y": 0,
          "w": 206,
          "h": 130
        }
      },
      {
        "item": "viz_8",
        "type": "block",
        "position": {
          "x": 0,
          "y": 130,
          "w": 1440,
          "h": 516
        }
      },
      {
        "item": "viz_9",
        "type": "block",
        "position": {
          "x": 0,
          "y": 646,
          "w": 480,
          "h": 320
